#!/usr/bin/env python3
"""Validate a prd-judge JSON report.

This is intentionally lightweight and stdlib-only so it works inside any Codex
session. It enforces the judgment contract, not a meta-score contract.
"""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path
from typing import Any

VERDICTS = {"GO", "REVISE", "HOLD", "WRONG_ARTIFACT", "DISQUALIFY_UNTIL_ARCHITECTURE_AUDIT"}
ARTIFACT_TYPES = {"full-prd", "prd-lite", "mini-prd", "rfp-rfi-response", "sales-artifact", "architecture-audit", "unknown"}
CONFIDENCE = {"high", "medium", "low"}
SEVERITIES = {"P0", "P1", "P2"}
EVIDENCE_STATUSES = {"used", "missing", "conflicting", "assumption", "summary"}
# `summary` is defined only for findings[].evidence (the judge's own verbatim-free
# characterization); the ledger documents sources, so it keeps the source vocabulary.
LEDGER_STATUSES = {"used", "missing", "conflicting", "assumption"}
# Verdicts that may never be GO: a sales artifact is the wrong artifact for PRD
# judgment, and an unknown type means classification itself failed.
GO_FORBIDDEN_TYPES = {"sales-artifact", "unknown"}
# RFP gates whose doctrinal severity is flatly P0 (rfp-rfi-gates.md): G2 non-responsive
# format/missing mandatory section, G3 maturity overclaim, G5 scope/commercial
# over-commitment. G1/G4 stay unpinned because doctrine defines legitimate P1 forms.
RFP_P0_GATES = {
    "G2", "G3", "G5",
    "rfp_compliance_or_format_gap",
    "rfp_maturity_overclaim",
    "rfp_scope_over_commitment",
}
HARD_GATES = {
    "wrong_artifact",
    "missing_evidence",
    "architecture_audit_required",
    "incumbent_replacement_gap",
    "ai_eval_gap",
    "regulated_controls_gap",
    "prd_lite_business_case_mismatch",
    "implementation_readiness_gap",
    "customer_value_or_roi_gap",
    "workflow_or_persona_gap",
    "data_integration_gap",
}
# Style/form flags live in their own top-level `style_flags` array, NOT in
# gates_fired. plain_language covers punctuation/diction; length was removed (2026-07-04)
# because the labeled corpus showed word count does not predict fit (GO PRD-Lites are the
# longest documents); the length budget is an authoring forcing function in prd_writer,
# not a judge criterion. coherence_gap (added 2026-07-06, UNVALIDATED prior) covers the
# sentence/paragraph read-through layer per references/coherence-readthrough.md.
STYLE_FLAGS = {"plain_language_gap", "coherence_gap"}
# RFP/RFI gate vocabulary, fixed (not an open "rfp_*" prefix that accepted any
# invented token). The canonical G1-G8 names are from references/output-contract.md
# and references/rfp-rfi-gates.md; the rfp_* aliases mirror labels/failure_taxonomy.
RFP_GATES = {
    "G1", "G2", "G3", "G4", "G5", "G6", "G7", "G8",
    "rfp_responsiveness_gap",
    "rfp_compliance_or_format_gap",
    "rfp_maturity_overclaim",
    "rfp_evidence_or_consistency_gap",
    "rfp_scope_over_commitment",
    "rfp_buyer_read_gap",
    "rfp_missing_win_theme",
    "rfp_correctness_gap",
}
FORBIDDEN_SCORE_KEYS = {
    "score",
    "overall_score",
    "meta_score",
    "average_score",
    "numeric_score",
    "weighted_score",
    "verdict_score",
    "grade",
    "rating",
    "points",
    "stars",
    "percentile",
}
P0_REQUIRED_VERDICTS = {"HOLD", "WRONG_ARTIFACT", "DISQUALIFY_UNTIL_ARCHITECTURE_AUDIT"}
REQUIRED_TOP_LEVEL = {
    "verdict": str,
    "artifact_type": str,
    "confidence": str,
    "summary": str,
    "gates_fired": list,
    "style_flags": list,
    "findings": list,
    "evidence_ledger": list,
    "required_next_actions": list,
}
REQUIRED_FINDING = {
    "severity": str,
    "title": str,
    "impact": str,
    "required_fix": str,
    "evidence": list,
}
REQUIRED_EVIDENCE = {
    "source": str,
    "status": str,
    "quote": str,
}
REQUIRED_LEDGER = {
    "source": str,
    "status": str,
    "notes": str,
}


def load_json(path: Path) -> tuple[Any | None, list[str]]:
    try:
        return json.loads(path.read_text(encoding="utf-8")), []
    except FileNotFoundError:
        return None, [f"file not found: {path}"]
    except (OSError, UnicodeDecodeError) as exc:
        return None, [f"unreadable file: {path}: {exc}"]
    except json.JSONDecodeError as exc:
        return None, [f"invalid JSON: {exc}"]


def _normalize(text: str) -> str:
    """Lowercase and collapse whitespace so verbatim matching ignores formatting noise."""
    return re.sub(r"\s+", " ", text).strip().lower()


def _load_reference_text(artifact_path: str | None, packet_path: str | None) -> tuple[str, list[str]]:
    """Concatenated text of the artifact and/or CE packet, used to verify status='used'
    quotes, plus load errors. An explicitly supplied reference that cannot be read is a
    validation ERROR (fail closed): silently skipping it disabled the fabricated-quote
    check exactly when the caller believed it was armed."""
    parts: list[str] = []
    errors: list[str] = []
    for candidate in (artifact_path, packet_path):
        if not candidate:
            continue
        path = Path(candidate)
        try:
            if path.suffix.lower() == ".docx":
                sys.path.insert(0, str(Path(__file__).resolve().parent))
                import prd_preflight  # lazy: keeps the common .md/.json path stdlib-only

                parts.append(prd_preflight.read_docx_text(path))
            else:
                parts.append(path.read_text(encoding="utf-8", errors="replace"))
        except (OSError, UnicodeDecodeError, SystemExit) as exc:
            errors.append(f"reference {path} was supplied but could not be read ({exc}); refusing to validate quotes fail-open")
    return "\n".join(parts), errors


def require_object(obj: Any, errors: list[str], ctx: str) -> bool:
    if not isinstance(obj, dict):
        errors.append(f"{ctx} must be an object")
        return False
    return True


def require_fields(obj: dict[str, Any], spec: dict[str, type], errors: list[str], ctx: str) -> None:
    for key, typ in spec.items():
        if key not in obj:
            errors.append(f"{ctx}.{key} is required")
            continue
        if not isinstance(obj[key], typ):
            errors.append(f"{ctx}.{key} must be {typ.__name__}")


def fields_conform(obj: dict[str, Any], spec: dict[str, type]) -> bool:
    """True when every required field is present AND correctly typed. Semantic checks
    must be skipped otherwise: `["P0"] not in SEVERITIES` raises TypeError on an
    unhashable value, so a malformed LLM report used to crash the validator instead of
    being rejected with a contract error."""
    return all(isinstance(obj.get(key), typ) for key, typ in spec.items())


def non_empty_string(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def find_forbidden_score_keys(obj: Any, path: str = "report") -> list[str]:
    """Walk the entire report tree, not just top level, so a nested score key
    (e.g. findings[].score or meta.overall_score) cannot defeat the no-meta-score
    invariant."""
    hits: list[str] = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            child = f"{path}.{key}"
            if key in FORBIDDEN_SCORE_KEYS:
                hits.append(child)
            hits.extend(find_forbidden_score_keys(value, child))
    elif isinstance(obj, list):
        for idx, item in enumerate(obj):
            hits.extend(find_forbidden_score_keys(item, f"{path}[{idx}]"))
    return hits


def validate(report: Any, reference_text: str | None = None, packet: dict[str, Any] | None = None) -> dict[str, Any]:
    errors: list[str] = []
    warnings: list[str] = []
    reference_norm = _normalize(reference_text) if reference_text else None

    if not require_object(report, errors, "report"):
        return {"ok": False, "errors": errors, "warnings": warnings}

    for path in sorted(find_forbidden_score_keys(report)):
        errors.append(f"forbidden score field '{path}' is not allowed; prd-judge emits a verdict, not a meta score")

    report = dict(report)

    before_required_errors = len(errors)
    require_fields(report, REQUIRED_TOP_LEVEL, errors, "report")
    if len(errors) > before_required_errors:
        return {"ok": False, "errors": errors, "warnings": warnings}

    if report["verdict"] not in VERDICTS:
        errors.append(f"verdict must be one of {sorted(VERDICTS)}")
    if report["artifact_type"] not in ARTIFACT_TYPES:
        errors.append(f"artifact_type must be one of {sorted(ARTIFACT_TYPES)}")
    if report["confidence"] not in CONFIDENCE:
        errors.append(f"confidence must be one of {sorted(CONFIDENCE)}")
    if not non_empty_string(report["summary"]):
        errors.append("summary must be a non-empty string")

    finding_severities: list[str] = []
    unacknowledged_p1 = 0
    used_quote_count = 0
    backed_gates: set[str] = set()
    finding_gate_values: set[str] = set()
    for idx, finding in enumerate(report["findings"]):
        ctx = f"findings[{idx}]"
        if not require_object(finding, errors, ctx):
            continue
        require_fields(finding, REQUIRED_FINDING, errors, ctx)
        if not fields_conform(finding, REQUIRED_FINDING):
            continue
        if "acknowledged" in finding and not isinstance(finding["acknowledged"], bool):
            errors.append(f"{ctx}.acknowledged must be a boolean when present")
        if finding["severity"] not in SEVERITIES:
            errors.append(f"{ctx}.severity must be one of {sorted(SEVERITIES)}")
        else:
            finding_severities.append(finding["severity"])
            if finding["severity"] == "P1" and finding.get("acknowledged") is not True:
                unacknowledged_p1 += 1
        # Strict output schemas force the gate key to always exist; an empty string
        # means "this finding backs no gate" (same convention as classification_override).
        if "gate" in finding and finding["gate"] != "":
            gate_value = finding["gate"]
            if not isinstance(gate_value, str) or (
                gate_value not in HARD_GATES and gate_value not in RFP_GATES
            ):
                errors.append(
                    f"{ctx}.gate {gate_value!r} is not a known hard gate; findings[].gate must be a "
                    "hard-gate token or an RFP G1-G8 name"
                )
            else:
                # A gate fires only on unacknowledged gaps: "never fire a gate and also
                # mark its finding acknowledged — that combination is a contradiction"
                # (deal-shape-gates). Owned means finding-only; unowned means gate.
                if finding.get("acknowledged") is True:
                    errors.append(
                        f"{ctx} is acknowledged but backs gate '{gate_value}'; an owned gap is a "
                        "finding, not a gate — drop the gate or the acknowledged flag"
                    )
                if gate_value in RFP_P0_GATES and finding["severity"] != "P0":
                    errors.append(
                        f"{ctx}.severity is {finding['severity']} but gate '{gate_value}' is "
                        "doctrinally P0 (rfp-rfi-gates: format non-compliance, maturity overclaim, "
                        "and scope over-commitment are disqualifying)"
                    )
                finding_gate_values.add(gate_value)
                if finding["severity"] in {"P0", "P1"}:
                    backed_gates.add(gate_value)
        for key in ("title", "impact", "required_fix"):
            if not non_empty_string(finding[key]):
                errors.append(f"{ctx}.{key} must be a non-empty string")
        if not finding["evidence"]:
            errors.append(f"{ctx}.evidence must include at least one evidence item or explicit absence")
        for eidx, evidence in enumerate(finding["evidence"]):
            ectx = f"{ctx}.evidence[{eidx}]"
            if not require_object(evidence, errors, ectx):
                continue
            require_fields(evidence, REQUIRED_EVIDENCE, errors, ectx)
            if not fields_conform(evidence, REQUIRED_EVIDENCE):
                continue
            if evidence["status"] not in EVIDENCE_STATUSES:
                errors.append(f"{ectx}.status must be one of {sorted(EVIDENCE_STATUSES)}")
            for key in ("source", "quote"):
                if not non_empty_string(evidence[key]):
                    errors.append(f"{ectx}.{key} must be a non-empty string")
            if evidence.get("status") == "used" and non_empty_string(evidence.get("quote", "")):
                used_quote_count += 1
                if reference_norm is not None and _normalize(evidence["quote"]) not in reference_norm:
                    errors.append(
                        f"{ectx}.quote has status 'used' but was not found verbatim in the artifact "
                        "or packet (normalized substring match); a used quote must be verbatim"
                    )

    # Fail closed on unverifiable quotes: a status='used' quote asserts verbatim text,
    # so validating it without the artifact/packet is exactly the fabricated-evidence
    # hole the eval measured (1.6% fabricated-quote rate on the old default invocation).
    if used_quote_count and reference_norm is None:
        errors.append(
            f"report cites {used_quote_count} status='used' quote(s) but no --artifact/--packet was "
            "provided; verbatim verification is required — rerun with the artifact"
        )

    for idx, row in enumerate(report["evidence_ledger"]):
        ctx = f"evidence_ledger[{idx}]"
        if not require_object(row, errors, ctx):
            continue
        require_fields(row, REQUIRED_LEDGER, errors, ctx)
        if not fields_conform(row, REQUIRED_LEDGER):
            continue
        if row["status"] not in LEDGER_STATUSES:
            errors.append(f"{ctx}.status must be one of {sorted(LEDGER_STATUSES)}")
        for key in ("source", "notes"):
            if not non_empty_string(row[key]):
                errors.append(f"{ctx}.{key} must be a non-empty string")

    # GO = fit for declared stage: no P0 ever, and every P1 must be acknowledged in
    # the artifact (named, owned, next step -> finding.acknowledged = true). The old
    # rule ("no P0/P1 at all") made GO definitionally unreachable for pre-sales
    # artifacts, which always carry future obligations.
    if report["verdict"] == "GO" and report["artifact_type"] in GO_FORBIDDEN_TYPES:
        errors.append(
            f"GO verdict on artifact_type '{report['artifact_type']}' is contradictory: a sales "
            "artifact is the wrong artifact for PRD judgment and an unknown type means "
            "classification failed; use WRONG_ARTIFACT or classify the artifact"
        )
    if report["verdict"] == "GO" and "P0" in finding_severities:
        errors.append("GO verdict cannot contain P0 findings")
    if report["verdict"] == "GO" and unacknowledged_p1:
        errors.append(
            f"GO verdict carries {unacknowledged_p1} unacknowledged P1 finding(s); GO requires every "
            "remaining P1 gap to be acknowledged in the artifact (finding.acknowledged = true)"
        )
    if "P0" in finding_severities and report["verdict"] not in P0_REQUIRED_VERDICTS:
        errors.append(
            f"a P0 finding requires verdict {sorted(P0_REQUIRED_VERDICTS)}; "
            f"verdict '{report['verdict']}' with a P0 finding is internally contradictory"
        )
    if report["verdict"] in P0_REQUIRED_VERDICTS and "P0" not in finding_severities:
        errors.append(f"{report['verdict']} verdict must include at least one P0 finding")
    if report["verdict"] == "GO" and report["confidence"] == "low":
        warnings.append("GO verdict at low confidence is internally contradictory; reconsider HOLD or raise confidence")
    if report["verdict"] != "GO" and not report["required_next_actions"]:
        errors.append("non-GO verdicts must include required_next_actions")
    for idx, action in enumerate(report["required_next_actions"]):
        if not non_empty_string(action):
            errors.append(f"required_next_actions[{idx}] must be a non-empty string")

    if not report["findings"] and report["verdict"] != "GO":
        errors.append("non-GO verdicts must include findings")
    if not report["evidence_ledger"]:
        errors.append("evidence_ledger must include at least the PRD source and missing/used context")

    # gates_fired is required (require_fields enforced presence and list type above).
    gates = report["gates_fired"]
    for idx, gate in enumerate(gates):
        if not isinstance(gate, str):
            errors.append(f"gates_fired[{idx}] must be a string")
            continue
        if gate in STYLE_FLAGS:
            errors.append(
                f"gates_fired[{idx}] '{gate}' is a style flag; put it in style_flags, not gates_fired"
            )
        elif gate not in HARD_GATES and gate not in RFP_GATES:
            errors.append(f"gates_fired[{idx}] '{gate}' is not a known hard gate")
    style_flags = report["style_flags"]
    for idx, flag in enumerate(style_flags):
        if not isinstance(flag, str) or flag not in STYLE_FLAGS:
            errors.append(f"style_flags[{idx}] {flag!r} is not a known style flag ({sorted(STYLE_FLAGS)})")
    if report["verdict"] == "GO" and gates:
        errors.append("GO verdict cannot list gates_fired")
    # Style flags do not decide shipability (2026-07-04, matches the labeling
    # guidelines and the adjudicated gold): a GO may carry style flags, but every
    # flag must come with a mandatory fix in required_next_actions.
    if report["verdict"] == "GO" and style_flags and not report["required_next_actions"]:
        errors.append(
            "GO with style_flags must include required_next_actions with the mandatory style fixes "
            "(plain-language rewrite and/or source-grounded scope reduction)"
        )
    # Every gate listed must be backed by a blocking finding that names it via
    # findings[].gate, and every finding.gate must be a gate the report actually fired
    # (output-contract: the linkage is enforced per-gate, not just "some P0/P1 exists").
    listed_gates = {g for g in gates if isinstance(g, str)}
    for gate in sorted(listed_gates):
        if gate not in backed_gates:
            errors.append(
                f"gates_fired lists '{gate}' but no P0/P1 finding backs it; set findings[].gate "
                f"= '{gate}' on the blocking finding"
            )
    for gate in sorted(finding_gate_values):
        if gate not in listed_gates:
            errors.append(
                f"a finding sets gate '{gate}' but it is not listed in gates_fired; add it to "
                "gates_fired or remove the finding's gate"
            )
    # Gate-to-verdict consistency, both directions where doctrine is unambiguous:
    # wrong_artifact <-> WRONG_ARTIFACT, and DISQUALIFY must be backed by an
    # architecture/incumbent gate. Architecture/incumbent gates are intentionally NOT
    # force-mapped TO DISQUALIFY; doctrine lets those roll to HOLD or acknowledged P1s.
    if "wrong_artifact" in listed_gates and report["verdict"] != "WRONG_ARTIFACT":
        errors.append(
            "gates_fired lists 'wrong_artifact' but the verdict is "
            f"'{report['verdict']}'; a wrong_artifact gate requires verdict WRONG_ARTIFACT"
        )
    if report["verdict"] == "WRONG_ARTIFACT" and "wrong_artifact" not in listed_gates:
        errors.append(
            "verdict WRONG_ARTIFACT requires the 'wrong_artifact' gate in gates_fired, backed by a "
            "P0 finding that says what the artifact actually is"
        )
    if report["verdict"] == "DISQUALIFY_UNTIL_ARCHITECTURE_AUDIT" and not (
        {"architecture_audit_required", "incumbent_replacement_gap"} & listed_gates
    ):
        errors.append(
            "verdict DISQUALIFY_UNTIL_ARCHITECTURE_AUDIT requires 'architecture_audit_required' or "
            "'incumbent_replacement_gap' in gates_fired"
        )
    # classification_override: the preflight wrong-artifact recommendation is binding
    # unless the judge writes an explicit override justification here. Strict output
    # schemas force the key to always exist, so an empty string means "no override".
    if "classification_override" in report and not isinstance(report["classification_override"], str):
        errors.append("classification_override must be a string (empty when not overriding)")

    # Packet-aware binding checks: with the CE packet supplied, the preflight
    # wrong-artifact recommendation is ENFORCED, not advisory prose. "Because I say so"
    # overrides are rejected; a substantive justification is at least 40 characters.
    if packet is not None and isinstance(packet, dict):
        pf = packet.get("preflight") or {}
        recommendations = set(pf.get("gate_recommendations") or [])
        override = report.get("classification_override")
        override_text = override.strip() if isinstance(override, str) else ""
        if "wrong_artifact_for_prd_judgment" in recommendations and report["verdict"] != "WRONG_ARTIFACT":
            if len(override_text) < 40:
                errors.append(
                    "the packet's preflight recommends wrong_artifact_for_prd_judgment; either return "
                    "verdict WRONG_ARTIFACT or justify grading it as a PRD in classification_override "
                    "(a substantive justification, at least 40 characters)"
                )
        pf_type = pf.get("artifact_type")
        if pf_type and pf_type != report["artifact_type"] and not override_text:
            warnings.append(
                f"report artifact_type '{report['artifact_type']}' differs from the packet preflight "
                f"'{pf_type}' with no classification_override; state why the classification changed"
            )

    # Reason first, then decide: the contract asks for `verdict` as the LAST key so the
    # findings are produced before the verdict is committed. Key order is advisory
    # discipline (a correct verdict is not wrong because of ordering), so this warns.
    keys = list(report)
    if keys and keys[-1] != "verdict":
        warnings.append(
            "verdict is not the last field in the report; the contract asks for findings before "
            "verdict (reason first, then decide)"
        )

    return {"ok": not errors, "errors": errors, "warnings": warnings}


def main(argv: list[str]) -> int:
    import argparse

    parser = argparse.ArgumentParser(prog="validate_report.py", description="Validate a prd-judge JSON report")
    parser.add_argument("report", help="Path to the prd-judge JSON report")
    parser.add_argument("--artifact", help="Optional PRD/spec artifact; status='used' quotes are checked verbatim against it")
    parser.add_argument("--packet", help="Optional CE packet JSON whose text also counts as a source for status='used' quotes")
    args = parser.parse_args(argv[1:])
    data, load_errors = load_json(Path(args.report))
    if load_errors:
        payload = {"ok": False, "errors": load_errors, "warnings": []}
        print(json.dumps(payload, indent=2, sort_keys=True))
        return 1
    reference_text: str | None = None
    reference_errors: list[str] = []
    if args.artifact or args.packet:
        reference_text, reference_errors = _load_reference_text(args.artifact, args.packet)
        reference_text = reference_text or None
    packet_data: dict[str, Any] | None = None
    if args.packet:
        packet_data, packet_errors = load_json(Path(args.packet))
        if packet_errors or not isinstance(packet_data, dict):
            reference_errors.append(f"packet {args.packet} is not readable JSON; binding checks cannot run")
            packet_data = None
    payload = validate(data, reference_text=reference_text, packet=packet_data)
    if reference_errors:
        payload["errors"] = reference_errors + payload["errors"]
        payload["ok"] = False
    print(json.dumps(payload, indent=2, sort_keys=True))
    return 0 if payload["ok"] else 1


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
